-- One-time reviewed 598-event historical repair. Generated from current production before-state.
-- This migration changes only qty and notes; all guards remain in force.
BEGIN;
CREATE TEMP TABLE repair_manifest (event_id uuid NOT NULL, expected_status text NOT NULL, old_qty numeric, new_qty numeric NOT NULL, old_notes text, new_notes text);
DO $verify$ DECLARE n integer; bad integer; BEGIN
 SELECT count(*) INTO n FROM repair_manifest; IF n <> 598 THEN RAISE EXCEPTION 'repair manifest count % != 598',n; END IF;
 SELECT count(*) INTO bad FROM repair_manifest m LEFT JOIN public.events e ON e.id=m.event_id WHERE e.id IS NULL; IF bad <> 0 THEN RAISE EXCEPTION 'missing target rows: %',bad; END IF;
 SELECT count(*) INTO bad FROM repair_manifest m JOIN public.events e ON e.id=m.event_id WHERE e.status IS DISTINCT FROM m.expected_status OR e.qty IS DISTINCT FROM m.old_qty OR e.notes IS DISTINCT FROM m.old_notes; IF bad <> 0 THEN RAISE EXCEPTION 'before-state mismatch rows: %',bad; END IF;
 SELECT count(*) INTO bad FROM repair_manifest m JOIN public.events e ON e.id=m.event_id JOIN public.items i ON i.id=e.item_id WHERE i.name ~* 'red[[:space:]]*bull' OR i.name ~* '(^|[[:space:]])water([[:space:]]|$)'; IF bad <> 0 THEN RAISE EXCEPTION 'Red Bull/Water target rows: %',bad; END IF;
END $verify$;
-- The existing guard recognizes this transaction-local role claim as its trusted maintenance context.
SELECT set_config('request.jwt.claim.role','service_role',true);
DO $post$ DECLARE n integer; bad integer; BEGIN
 UPDATE public.events e SET qty=m.new_qty, notes=m.new_notes FROM repair_manifest m WHERE e.id=m.event_id AND e.status IS NOT DISTINCT FROM m.expected_status AND e.qty IS NOT DISTINCT FROM m.old_qty AND e.notes IS NOT DISTINCT FROM m.old_notes;
 GET DIAGNOSTICS n = ROW_COUNT; IF n <> 598 THEN RAISE EXCEPTION 'updated rows % != 598',n; END IF;
 SELECT count(*) INTO bad FROM repair_manifest m JOIN public.events e ON e.id=m.event_id WHERE e.qty IS DISTINCT FROM m.new_qty OR e.notes IS DISTINCT FROM m.new_notes OR e.status IS DISTINCT FROM m.expected_status; IF bad <> 0 THEN RAISE EXCEPTION 'post-state mismatch rows: %',bad; END IF;
END $post$;
COMMIT;
